package dev.eugheist.ttmodern;
final class AspectAnalyzerAudit {
 static void run(net.minecraft.server.level.ServerLevel world,net.minecraft.core.BlockPos at){
  world.setBlock(at,AspectAnalyzer.BLOCK.get().defaultBlockState(),3);var tile=(AspectAnalyzer.Entity)world.getBlockEntity(at);
  var peripheral=(ComputerCraftCompat.AnalyzerPeripheral)world.getCapability(dan200.computercraft.api.peripheral.PeripheralCapability.get(),at,net.minecraft.core.Direction.NORTH);
  if(peripheral==null||peripheral.hasItem()||peripheral.itemHasAspects()||!peripheral.getAspects().isEmpty()||!peripheral.getAspectCount().isEmpty())throw new IllegalStateException("CC empty analyzer");
  var items=world.getCapability(net.neoforged.neoforge.capabilities.Capabilities.ItemHandler.BLOCK,at,net.minecraft.core.Direction.DOWN);
  var stack=new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.STONE,64);stack.set(net.minecraft.core.component.DataComponents.CUSTOM_NAME,net.minecraft.network.chat.Component.literal("Analyzer conservation fixture"));
  if(items==null||!items.insertItem(0,stack,false).isEmpty()||!peripheral.hasItem()||!peripheral.itemHasAspects())throw new IllegalStateException("CC analyzer automation");
  var expected=dev.eugheist.tc4modern.RecipeAspects.get(stack,world);var counts=peripheral.getAspectCount();for(var entry:expected.entrySet())if(counts.getOrDefault(entry.getKey(),-1d)!=entry.getValue().doubleValue())throw new IllegalStateException("CC analyzer exact tags/counts");
  if(counts.size()!=expected.size()||peripheral.getAspects().size()!=expected.size())throw new IllegalStateException("CC analyzer table sizes");
  var saved=tile.saveWithoutMetadata(world.registryAccess());tile.inventory.setStackInSlot(0,net.minecraft.world.item.ItemStack.EMPTY);tile.loadWithComponents(saved,world.registryAccess());if(!net.minecraft.world.item.ItemStack.matches(stack,tile.inventory.getStackInSlot(0)))throw new IllegalStateException("CC analyzer persistence count/components");
  var player=net.neoforged.neoforge.common.util.FakePlayerFactory.get(world,new com.mojang.authlib.GameProfile(java.util.UUID.fromString("53cf8775-84e8-4acf-8191-921ade436722"),"TTAnalyzerAudit"));var backup=new java.util.ArrayList<net.minecraft.world.item.ItemStack>();for(int i=0;i<player.getInventory().getContainerSize();i++)backup.add(player.getInventory().getItem(i).copy());var position=player.position();
  try{player.getInventory().clearContent();player.setPos(net.minecraft.world.phys.Vec3.atCenterOf(at));var menu=new AspectAnalyzerMenu(91,player.getInventory(),tile);if(!menu.stillValid(player)||menu.slots.size()!=37)throw new IllegalStateException("CC analyzer menu slots/reach");if(menu.quickMoveStack(player,0).getCount()!=64||!tile.inventory.getStackInSlot(0).isEmpty())throw new IllegalStateException("CC analyzer shift to player");int source=-1;for(int i=1;i<37;i++)if(menu.slots.get(i).hasItem())source=i;if(source<0||menu.quickMoveStack(player,source).getCount()!=64||!net.minecraft.world.item.ItemStack.matches(stack,tile.inventory.getStackInSlot(0)))throw new IllegalStateException("CC analyzer shift back conservation");player.setPos(position.add(100,0,0));if(menu.stillValid(player)||!menu.quickMoveStack(player,0).isEmpty())throw new IllegalStateException("CC analyzer distance gate");}
  finally{tile.inventory.setStackInSlot(0,net.minecraft.world.item.ItemStack.EMPTY);player.getInventory().clearContent();for(int i=0;i<backup.size();i++)player.getInventory().setItem(i,backup.get(i));player.setPos(position);}
  if(thaumcraft.api.research.ResearchCategories.getResearch("ASPECT_ANALYZER")==null||ThaumicTinkererModern.ARCANE_RECIPES.stream().noneMatch(r->r.key().equals("ASPECT_ANALYZER")))throw new IllegalStateException("CC analyzer research/recipe");
  System.out.println("TT CC ANALYZER AUDIT: ALL PASS (native capability,automation64,read conservation,NBT components,37slot menu,shift both ways,distance gate,research/recipe)");
 }
}
